            out_c = c - min_c + offset
            if 0 <= out_r < max_S and 0 <= out_c < max_S:
                out_grid[out_r][out_c] = color

    # Mirroring to fix any cropped bottom/right parts
    # Assuming symmetric shapes centered in the output grid
    for r in range(max_S):
